<!DOCTYPE html>
<html <?php language_attributes();?>><head><meta charset="<?php bloginfo('charset');?>"><meta name="viewport" content="width=device-width, initial-scale=1.0"><?php wp_head();?></head><body <?php body_class();?>><?php wp_body_open();?><div class="site-wrapper"><aside class="sidebar"><div class="sidebar-top"><div class="logo-container"><a href="<?php echo esc_url(home_url('/'));?>" id="logo-link"><?php $saved_index=isset($_COOKIE['studio94_active_logo'])?intval($_COOKIE['studio94_active_logo']):0;if($saved_index<0||$saved_index>3){$saved_index=0;} $logos=['logo_v1.svg','logo_v2.svg','logo_v3.svg','logo_v4.svg'];$active_logo=$logos[$saved_index];?><img id="dynamic-logo" class="logo-desktop" src="<?php echo esc_url(get_template_directory_uri().'/assets/images/'.$active_logo);?>" alt="<?php bloginfo('name');?>"><img class="logo-mobile" src="<?php echo esc_url(get_template_directory_uri().'/assets/images/wordmark_v1.svg');?>" alt="<?php bloginfo('name');?>"></a></div><button id="mobile-menu-btn" class="mobile-menu-toggle">☰</button></div><nav id="mobile-nav-container" class="nav-container"><?php wp_nav_menu(['theme_location'=>'sidebar_menu','container'=>false,'menu_class'=>'main-nav','fallback_cb'=>false]);?><a href="<?php echo esc_url(wc_get_cart_url());?>" class="cart-widget">Cart (<span class="cart-count"><?php echo WC()->cart?WC()->cart->get_cart_contents_count():0;?></span>)</a></nav></aside><main class="main-content"><script>document.getElementById('mobile-menu-btn').addEventListener('click',function(){document.getElementById('mobile-nav-container').classList.toggle('active');});let lastScrollTop=0;const mobileSidebar=document.querySelector('.sidebar');window.addEventListener('scroll',function(){if(window.innerWidth<=768){let scrollTop=window.pageYOffset||document.documentElement.scrollTop;if(scrollTop>lastScrollTop&&scrollTop>50){mobileSidebar.classList.add('nav-hidden');document.getElementById('mobile-nav-container').classList.remove('active');}else{mobileSidebar.classList.remove('nav-hidden');}lastScrollTop=scrollTop;}});document.addEventListener('DOMContentLoaded',function(){const anchorLinks=document.querySelectorAll('a[href^="#"]');anchorLinks.forEach(link=>{link.addEventListener('click',function(e){const targetId=this.getAttribute('href');if(targetId==='#')return;const targetElement=document.querySelector(targetId);if(targetElement){e.preventDefault();targetElement.scrollIntoView({behavior:'smooth',block:'start'});if(history.pushState){history.pushState(null,null,targetId);}else{location.hash=targetId;}}});});});document.addEventListener('DOMContentLoaded',function(){const logoImg=document.getElementById('dynamic-logo');const logoWrapper=document.getElementById('logo-link');if(logoImg&&logoWrapper){const basePath='<?php echo esc_url(get_template_directory_uri().'/assets/images/'); ?>';const logos=['logo_v1.svg','logo_v2.svg','logo_v3.svg','logo_v4.svg'];let currentLogoIndex=<?php echo $saved_index;?>;logoWrapper.addEventListener('mouseenter',function(){if(logoImg.classList.contains('is-animating'))return;logoImg.classList.add('is-animating');currentLogoIndex=(currentLogoIndex+1)%logos.length;document.cookie="studio94_active_logo="+currentLogoIndex+"; path=/; max-age=31536000";logoImg.classList.add('flip-out');setTimeout(function(){logoImg.src=basePath+logos[currentLogoIndex];logoImg.classList.remove('flip-out');logoImg.classList.add('flip-in');void logoImg.offsetWidth;logoImg.classList.remove('flip-in');setTimeout(function(){logoImg.classList.remove('is-animating');},250);},250);});} if(typeof jQuery!=='undefined'){jQuery(document.body).on('added_to_cart',function(e,fragments,hash,$btn){var addedQty=1;if($btn){var $qty=$btn.closest('form').find('input.qty');if($qty.length){addedQty=parseInt($qty.val())||1;}else if($btn.data('quantity')){addedQty=parseInt($btn.data('quantity'))||1;}}var cartWidget=document.querySelector('.cart-widget');var cartCountEl=document.querySelector('.cart-widget .cart-count');if(cartCountEl){cartCountEl.innerText=(parseInt(cartCountEl.innerText)||0)+addedQty;if(cartWidget){cartWidget.style.transform='scale(1.05)';cartWidget.style.backgroundColor='var(--brand-rose-light)';cartWidget.style.color='var(--brand-rose)';setTimeout(()=>{cartWidget.style.transform='';cartWidget.style.backgroundColor='';cartWidget.style.color='';},400);}}});}});</script>